157	        List<Period> made = generateFiscalYear(sheetId, user, year + 1);
158	        LocalDate newFirst = start.plusMonths(12).atDay(1);
159	        LocalDate newLast = start.plusMonths(23).atEndOfMonth();
160	        Period first = periods.findBySheetIdOrderByFromDateAsc(sheetId).stream()
161	                .filter(p -> !p.getFromDate().isBefore(newFirst) && !p.getFromDate().isAfter(newLast))
162	                .findFirst().orElse(null);
