164	            for (Person person : sheetPeople) {
165	                BigDecimal amount = open.get(person.getId());
166	                if (amount.signum() <= 0) continue;
167	                first.addOpening(person.getId(), amount);
168	                audit.recordOnCommit("OPENING_SET sheet=" + sheetId + " by=" + user.strip()
169	                        + " name=" + person.getName() + " period=" + first.getName()
170	                        + " amount=" + amount.setScale(2).toPlainString());
171	            }
172	            periods.saveAndFlush(first);
173	        }
174	        audit.recordOnCommit("ROLLOVER sheet=" + sheetId + " by=" + user.strip()
175	                + " fy=FY" + year + " periods=" + made.size());
176	        return made;
