239	    /** Close or soft-close the period, fixing each person's due-total for it and its own, and audit it. */
240	    private Period fix(String sheetId, String user, Period period, LocalDate today, boolean auto, boolean soft) {
241	        Map<Long, Person> byId = people.findBySheetIdOrderByPositionAscIdAsc(sheetId).stream()
242	                .collect(Collectors.toMap(Person::getId, Function.identity()));
243	        // Every person on the sheet gets a figure, 0.00 when none of their claims falls in it.
244	        Map<Long, BigDecimal> personDues = new LinkedHashMap<>();
245	        for (Long personId : byId.keySet()) personDues.put(personId, BigDecimal.ZERO.setScale(2));
246	        Map<Long, BigDecimal> personCarried = new LinkedHashMap<>(personDues);
247	        // their opening balances for it are part of what they carry into it
248	        period.getOpenings().forEach((personId, amount) -> {
