250	        });
251	        List<Period> all = periods.findBySheetIdOrderByFromDateAsc(sheetId);
252	        for (Claim claim : claims.findBySheetIdOrderByIdDesc(sheetId)) {
253	            Person person = byId.get(claim.getPersonId());
254	            if (person == null || !person.countsAt(claim, period.getToDate(), today)) continue;
255	            if (period.contains(claim.getDueBy())) {
256	                BigDecimal figure = claimService.chargedFigureOf(sheetId, person, claim);
257	                if (figure != null) personDues.merge(person.getId(), figure, BigDecimal::add);
