264	        List<PoolCutLine> cuts = new ArrayList<>();
265	        for (PoolService.PoolLine pool : pools.pools(sheetId)) {
266	            for (PoolService.Member m : pool.members()) {
267	                cuts.add(new PoolCutLine(pool.id(), pool.crewId(), m.personId(), m.poolId(), m.cut()));
268	            }
269	        }
270	        period.fixPoolCuts(cuts);
271	        if (soft) period.softClose(personDues, personCarried);
272	        else period.close(personDues, personCarried);
273	        Period saved = periods.saveAndFlush(period);
274	        audit.recordOnCommit((soft ? "PERIOD_SOFT_CLOSED" : "PERIOD_CLOSED") + " sheet=" + sheetId + " by=" + user.strip()
275	                + " period=" + saved.getName() + " total=" + saved.getClosedDueTotal().setScale(2).toPlainString()
276	                + (auto ? " auto=yes" : ""));
